  "Delete saved quiz": { es: "Borrar cuestionario guardado", ar: "احذف الاختبار المحفوظ", zh: "删除已保存的测验", sw: "Futa jaribio lililohifadhiwa", sv: "Radera sparat quiz" },
  "No questions yet — add suggested ones or write your own.": { es: "Aún no hay preguntas: añade sugeridas o escribe las tuyas.", ar: "لا أسئلة بعد — أضف أسئلة مقترحة أو اكتب أسئلتك.", zh: "还没有题目——添加推荐题或自己写。", sw: "Bado hakuna maswali — ongeza yaliyopendekezwa au andika yako.", sv: "Inga frågor än — lägg till föreslagna eller skriv egna." },
  "▶ Play my quiz": { es: "▶ Jugar mi cuestionario", ar: "▶ العب اختباري", zh: "▶ 玩我的测验", sw: "▶ Cheza jaribio langu", sv: "▶ Spela mitt quiz" },
