  "e.g. How vaccines work": { es: "p. ej. Cómo funcionan las vacunas", ar: "مثلًا: كيف تعمل اللقاحات", zh: "例如：疫苗如何起作用", sw: "k.m. Jinsi chanjo zinavyofanya kazi", sv: "t.ex. Hur vacciner fungerar" },
  "e.g. The heart — Year 7 quiz": { es: "p. ej. El corazón: cuestionario de 1.º de ESO", ar: "مثلًا: القلب — اختبار الصف السابع", zh: "例如：心脏——七年级测验", sw: "k.m. Moyo — jaribio la Darasa la 7", sv: "t.ex. Hjärtat — quiz för åk 7" },
  "How to use Body Map": { es: "Cómo usar Body Map", ar: "كيفية استخدام Body Map", zh: "如何使用 Body Map", sw: "Jinsi ya kutumia Body Map", sv: "Så använder du Body Map" },
  "Body Map — how every body part works, its illnesses and care, digestion, fasting and quizzes | MigaBuilder": { es: "Body Map — cómo funciona cada parte del cuerpo, sus enfermedades y cuidados, la digestión, el ayuno y cuestionarios | MigaBuilder", ar: "Body Map — كيف يعمل كل جزء من الجسم وأمراضه والعناية به والهضم والصيام والاختبارات | MigaBuilder", zh: "Body Map — 每个身体部位如何工作、疾病与护理、消化、禁食和测验 | MigaBuilder", sw: "Body Map — jinsi kila sehemu ya mwili inavyofanya kazi, magonjwa na utunzaji, mmeng'enyo, kufunga na majaribio | MigaBuilder", sv: "Body Map — hur varje kroppsdel fungerar, sjukdomar och vård, matsmältning, fasta och quiz | MigaBuilder" },
  "Fingertip — tap for the skin overview": { es: "Yema del dedo: toca para ver la piel en general", ar: "طرف الإصبع — انقر لنظرة عامة على الجلد", zh: "指尖——点击查看皮肤概览", sw: "Ncha ya kidole — gusa kwa muhtasari wa ngozi", sv: "Fingertopp — tryck för översikt över huden" },
  "Cut-through view of the skin": { es: "Vista en corte de la piel", ar: "مقطع للجلد", zh: "皮肤剖面图", sw: "Mwonekano wa mkato wa ngozi", sv: "Genomskärning av huden" },
  "Epidermis": { es: "Epidermis", ar: "البشرة", zh: "表皮", sw: "Epidemisi", sv: "Epidermis" },
