  "Sweat pore": { es: "Poro sudoríparo", ar: "مسام العرق", zh: "汗孔", sw: "Kitundu cha jasho", sv: "Svettpor" },
  "Oil gland": { es: "Glándula sebácea", ar: "غدة دهنية", zh: "皮脂腺", sw: "Tezi ya mafuta", sv: "Talgkörtel" },
  "Touch sensors": { es: "Sensores del tacto", ar: "مستشعرات اللمس", zh: "触觉感受器", sw: "Vihisi vya mguso", sv: "Beröringssensorer" },
  "Tap a bone. Tap the outline for bones in general.": { es: "Toca un hueso. Toca el contorno para los huesos en general.", ar: "انقر على عظمة. انقر على الحدود للعظام عمومًا.", zh: "点击一块骨头。点击轮廓查看骨骼总体介绍。", sw: "Gusa mfupa. Gusa mpaka kwa mifupa kwa ujumla.", sv: "Tryck på ett ben. Tryck på konturen för skelettet i allmänhet." },
  "Tap a layer or structure.": { es: "Toca una capa o estructura.", ar: "انقر على طبقة أو بنية.", zh: "点击一个层或结构。", sw: "Gusa tabaka au muundo.", sv: "Tryck på ett lager eller en struktur." },
  "↺ Front view": { es: "↺ Vista frontal", ar: "↺ منظر أمامي", zh: "↺ 正面视图", sw: "↺ Mwonekano wa mbele", sv: "↺ Framifrån" },
  "Explain the": { es: "Explica el", ar: "اشرح", zh: "解释", sw: "Eleza", sv: "Förklara" },
